package io.github.mekkiamiri.ratchet.order.web;

import io.github.mekkiamiri.ratchet.order.domain.ConcurrentOrderUpdateException;
import io.github.mekkiamiri.ratchet.order.domain.InvalidOrderException;
import io.github.mekkiamiri.ratchet.order.domain.OrderNotFoundException;
import jakarta.servlet.http.HttpServletRequest;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;

/**
 * La traduction exception métier vers code HTTP vit ici, pas dans le domaine.
 *
 * <p>Les exceptions standard de Spring MVC (requête mal formée, validation, ressource absente...)
 * sont traduites par {@link ResponseEntityExceptionHandler}. Tout le reste est une panne : on la
 * journalise avec sa pile pour que l'exploitation la voie dans la console du conteneur.
 */
@RestControllerAdvice
public class OrderExceptionHandler extends ResponseEntityExceptionHandler {

    private static final Logger LOG = LoggerFactory.getLogger(OrderExceptionHandler.class);

    @ExceptionHandler(OrderNotFoundException.class)
    public ProblemDetail notFound(OrderNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(InvalidOrderException.class)
    public ProblemDetail invalid(InvalidOrderException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.UNPROCESSABLE_CONTENT, e.getMessage());
    }

    @ExceptionHandler(ConcurrentOrderUpdateException.class)
    public ProblemDetail conflict(ConcurrentOrderUpdateException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, e.getMessage());
    }

    @ExceptionHandler(Exception.class)
    public ProblemDetail unexpected(Exception e, HttpServletRequest request) {
        LOG.error("Échec inattendu sur {} {}", request.getMethod(), request.getRequestURI(), e);
        return ProblemDetail.forStatusAndDetail(HttpStatus.INTERNAL_SERVER_ERROR, "Erreur interne");
    }
}
EOF
